        [
            'id' => 'diabetes', 'title' => 'Diabetes Management', 'icon' => 'fi-rs-glucose',
            'items' => [
                ['q' => 'Can diabetes be cured?', 'a' => 'Diabetes is generally a lifelong condition that is controlled rather than cured. With the right diet, activity, weight control and medicines, many people keep their sugar in range and live healthy lives.'],
                ['q' => 'Does diabetes affect surgery?', 'a' => 'It can. Poorly controlled sugar can slow wound healing and raise the risk of infection. If you need surgery, our team will optimise your sugar levels beforehand and monitor them closely afterwards.'],
